namespace RecipeCircle.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeCircle.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one ingredient is required.")]
    [MinLength(1, ErrorMessage = "At least one ingredient is required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one step is required.")]
    [MinLength(1, ErrorMessage = "At least one step is required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeCircle.Models;

namespace RecipeCircle.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new Recipe
        {
            Id = 1, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Baguette", "Tomatoes", "Basil", "Garlic", "Olive oil"],
            Steps = ["Slice and toast baguette.", "Dice tomatoes with basil and garlic.", "Top bread with mixture and drizzle olive oil."],
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Mushrooms", "Cream cheese", "Breadcrumbs", "Parmesan", "Garlic"],
            Steps = ["Remove mushroom stems.", "Mix filling ingredients.", "Stuff caps and bake at 375°F for 20 minutes."],
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Spaghetti", "Eggs", "Pecorino Romano", "Guanciale", "Black pepper"],
            Steps = ["Cook pasta al dente.", "Crisp guanciale in a pan.", "Whisk eggs with cheese.", "Toss hot pasta with egg mixture and guanciale."],
            AverageRating = 4.8, RatingCount = 25
        },
        new Recipe
        {
            Id = 4, Title = "Chicken Tikka Masala", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Chicken thighs", "Yogurt", "Tomato sauce", "Garam masala", "Cream", "Rice"],
            Steps = ["Marinate chicken in yogurt and spices.", "Grill or bake chicken.", "Simmer sauce with tomatoes, spices, and cream.", "Add chicken to sauce and serve with rice."],
            AverageRating = 4.7, RatingCount = 18
        },
        new Recipe
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour"],
            Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold in chocolate mixture and flour.", "Bake at 425°F for 12 minutes."],
            AverageRating = 4.9, RatingCount = 30
        },
        new Recipe
        {
            Id = 6, Title = "Tiramisu", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Ladyfingers", "Mascarpone", "Espresso", "Eggs", "Sugar", "Cocoa powder"],
            Steps = ["Brew espresso and let cool.", "Beat egg yolks with sugar, fold in mascarpone.", "Dip ladyfingers in espresso.", "Layer mascarpone and ladyfingers, dust with cocoa."],
            AverageRating = 4.6, RatingCount = 15
        }
    ];

    public List<Recipe> GetByCategory(string categorySlug)
    {
        return _recipes.Where(r => r.CategorySlug == categorySlug).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var categorySlug = submission.Category.ToLower().Replace(" ", "-");
        _recipes.Add(new Recipe
        {
            Id = _recipes.Max(r => r.Id) + 1,
            Title = submission.Title,
            Category = submission.Category,
            CategorySlug = categorySlug,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

@page "/recipes"
@page "/recipes/{CategorySlug}"
@using RecipeCircle.Models
@using RecipeCircle.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes - RecipeCircle</PageTitle>

@if (string.IsNullOrEmpty(CategorySlug))
{
    <h1>Browse Recipes</h1>
    <p>Select a category to browse:</p>
    <ul>
        <li><a href="recipes/appetizers">🥗 Appetizers</a></li>
        <li><a href="recipes/main-courses">🍝 Main Courses</a></li>
        <li><a href="recipes/desserts">🍰 Desserts</a></li>
    </ul>
}
else
{
    <h1>@CategoryDisplay</h1>
    <p><a href="recipes">← Back to all categories</a></p>

    @if (recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategorySlug { get; set; }

    private List<Recipe> recipes = [];

    private string CategoryDisplay => CategorySlug switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        _ => CategorySlug ?? "Recipes"
    };

    protected override void OnParametersSet()
    {
        if (!string.IsNullOrEmpty(CategorySlug))
        {
            recipes = RecipeService.GetByCategory(CategorySlug);
        }
    }
}

@page "/recipe/{Id:int}"
@using RecipeCircle.Models
@using RecipeCircle.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeCircle</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p><a href="recipes/@recipe.CategorySlug">← Back to @recipe.Category</a></p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li>@step</li>
        }
    </ol>

    <hr />
    <h3>Rating</h3>
    <p>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>

    <StarRating RecipeId="recipe.Id" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@using RecipeCircle.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    @if (submitted)
    {
        <p class="text-success">✓ Thanks for rating this recipe @selectedRating/5 stars!</p>
    }
    else
    {
        <p>Rate this recipe:</p>
        <div>
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <button class="btn btn-link fs-4 p-0 me-1"
                        @onclick="() => SubmitRating(star)"
                        title="@star stars">
                    @(star <= hoveredStar ? "★" : "☆")
                    @* Show filled stars up to hover position *@
                </button>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoveredStar;
    private int selectedRating;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

@page "/submit"
@using RecipeCircle.Models
@using RecipeCircle.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeCircle</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="submission.Title" />
        <ValidationMessage For="() => submission.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
            <option value="">-- Select a category --</option>
            <option value="Appetizers">Appetizers</option>
            <option value="Main Courses">Main Courses</option>
            <option value="Desserts">Desserts</option>
        </InputSelect>
        <ValidationMessage For="() => submission.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients" />
        <ValidationMessage For="() => submission.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="submission.Steps" />
        <ValidationMessage For="() => submission.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission submission = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(submission);
        successMessage = $"'{submission.Title}' has been submitted successfully!";
        submission = new();
    }
}

