toolArgs.file_text:
@page "/recipes"
@page "/recipes/{CategorySlug}"
@using RecipeCircle.Models
@using RecipeCircle.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes - RecipeCircle</PageTitle>

@if (string.IsNullOrEmpty(CategorySlug))
{
    <h1>Browse Recipes</h1>
    <p>Select a category to browse:</p>
    <ul>
        <li><a href="recipes/appetizers">🥗 Appetizers</a></li>
        <li><a href="recipes/main-courses">🍝 Main Courses</a></li>
        <li><a href="recipes/desserts">🍰 Desserts</a></li>
    </ul>
}
else
{
    <h1>@CategoryDisplay</h1>
    <p><a href="recipes">← Back to all categories</a></p>

    @if (recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategorySlug { get; set; }

    private List<Recipe> recipes = [];

    private string CategoryDisplay => CategorySlug switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        _ => CategorySlug ?? "Recipes"
    };

    protected override void OnParametersSet()
    {
        if (!string.IsNullOrEmpty(CategorySlug))
        {
            recipes = RecipeService.GetByCategory(CategorySlug);
        }
    }
}

@page "/recipe/{Id:int}"
@using RecipeCircle.Models
@using RecipeCircle.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeCircle</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p><a href="recipes/@recipe.CategorySlug">← Back to @recipe.Category</a></p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li>@step</li>
        }
    </ol>

    <hr />
    <h3>Rating</h3>
    <p>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>

    <StarRating RecipeId="recipe.Id" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@using RecipeCircle.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    @if (submitted)
    {
        <p class="text-success">✓ Thanks for rating this recipe @selectedRating/5 stars!</p>
    }
    else
    {
        <p>Rate this recipe:</p>
        <div>
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <button class="btn btn-link fs-4 p-0 me-1"
                        @onclick="() => SubmitRating(star)"
                        title="@star stars">
                    @(star <= hoveredStar ? "★" : "☆")
                    @* Show filled stars up to hover position *@
                </button>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoveredStar;
    private int selectedRating;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

